#!/usr/bin/env python3
"""Self-contained human-readable 50-symbol replay report; no network assets."""
import argparse
import collections
import datetime as dt
import html
import json
from pathlib import Path
import subprocess


def assemble(baseline, breadth, strategies=None, checks=None):
    """Keep measured populations explicit; never replace later losses with selected PF."""
    for run in (baseline, breadth):
        assert len(run['symbols']) == 50 and len(set(run['symbols'])) == 50
        assert run['hours'] == 24 and len(run['settled_hourly']) == 24
        assert sum(r['orders'] for r in run['settled_hourly']) == run['all']['orders']
        assert abs(sum(r['net_pct'] for r in run['settled_hourly']) - run['all']['net_pct']) < .03
    assert baseline['symbols'] == breadth['symbols']
    assert (baseline['start_utc'], baseline['end_utc']) == (breadth['start_utc'], breadth['end_utc'])
    return dict(baseline=baseline, breadth=breadth, strategies=strategies or {}, checks=checks or {})


